/**
 * Font catalog for certificate text.
 *
 * `bundled: true` entries are self-hosted woff2 files declared in fonts.css
 * (generated by scripts/vendor-fonts.mjs) so the admin preview and the
 * participant download render identically. The remaining entries rely on fonts
 * that ship with every desktop OS and need no download at all.
 */
export interface CertificateFont {
  id: string;
  label: string;
  /** CSS font-family list, quoted family first. */
  stack: string;
  weights: number[];
  italic: boolean;
  bundled: boolean;
}

