export const DEFAULT_CERTIFICATE_FONT = 'playfair-display';
export const DEFAULT_CERTIFICATE_BODY_FONT = 'inter';

export function findCertificateFont(id: string): CertificateFont {
  return CERTIFICATE_FONTS.find((font) => font.id === id) || CERTIFICATE_FONTS[0];
}

export function certificateFontStack(id: string): string {
  return findCertificateFont(id).stack;
}

/** First family in the stack, used when asking the browser to load the face. */
export function certificateFontFamily(id: string): string {
  const first = certificateFontStack(id).split(',')[0].trim();

  return first.replace(/^['"]|['"]$/g, '');
}

/** Nearest weight the family actually ships, so the browser never synthesises. */
export function nearestWeight(font: CertificateFont, weight: number): number {
  return font.weights.reduce(
    (best, candidate) => (Math.abs(candidate - weight) < Math.abs(best - weight) ? candidate : best),
    font.weights[0]
  );
}
